/**
 * Custom Cloudflare Worker entry point.
 *
 * OpenNext's generated worker exposes the fetch handler by default. The
 * application also uses OpenNext's Durable Object cache adapters, so their
 * classes must be re-exported by the actual Wrangler entry point in order for
 * Cloudflare to register the bindings declared in wrangler.jsonc.
 *
 * `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
 */
// @ts-ignore -- generated by the OpenNext build before Wrangler bundles this entry.
import handler from './.open-next/worker.js';

// @ts-ignore -- generated by the OpenNext build and exported by its worker bundle.
export { DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js';

export default {
  fetch: handler.fetch,
};
